css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .fila-pos{display: flex; gap: 7px; flex-wrap: wrap; margin-bottom: 12px;}
.mz .fila-pos .casilla{width: 52px; height: 52px; border: 1.5px solid var(--bosque); border-radius: 6px; display: flex; align-items: center; justify-content: center; font-size: 17px; font-weight: 700;}
.mz .preg-pos{font-size: 15px; font-weight: 600; line-height: 2.3;}
.mz .preg-pos .hueco{display: inline-block; width: 90px; border-bottom: 1.5px solid var(--bosque);}
.mz .esc-fila{display: flex; align-items: center; gap: 12px; font-size: 17px; font-weight: 700; margin-bottom: 12px;}
.mz .esc-fila .cif{min-width: 52px;}
.mz .esc-fila .linea-esc{flex: 1; border-bottom: 1.5px solid var(--bosque); height: 28px;}
.mz .prob{border: 1.5px solid var(--bosque); border-radius: 10px; padding: 12px 14px; font-size: 15px; font-weight: 600; line-height: 1.4;}
.mz .prob .linea-resp{border-bottom: 1.5px solid var(--bosque); height: 30px; margin-top: 12px;}
.mz .ordena-fila{display: flex; align-items: center; gap: 10px; flex-wrap: wrap; font-size: 16px; font-weight: 700; margin-bottom: 10px;}
.mz .ordena-fila .ban{border: 1.5px solid var(--bosque); border-radius: 6px; padding: 6px 12px;}
.mz .ordena-casillas{display: flex; gap: 8px; margin-top: 4px;}
.mz .ordena-casillas .hco{width: 56px; height: 48px; border: 1.5px solid var(--bosque); border-radius: 6px;}
.mz .prob{line-height: 1.725 !important;}
